        answer: 'Si alaamaaji diine ɗon ndaɗa, AWA waaway ndaaragoo juutugol ndiyam caggal danyugo e hollugo alaamaare nifas dow ko diine suɓaaɗo wi’i. Ñalɗi ɗi ɓurdi juuti ɗon waaway wayloyaago hakkunde fedde hiitaaɗe, e ɗum holletaake bana goonga gootuɗum nokkuuji ɗi yimɓe hawtaaki.'
